from collections import Counter

def transform(grid):
    counts = Counter(value for row in grid for value in row)
    # The more common color becomes 0; the less common color becomes
    # the original more-common color.
    dominant = max(counts, key=counts.get)
    mapping = {dominant: 0}
    for color in counts:
        if color != dominant:
            mapping[color] = dominant
    return [[mapping[value] for value in row] for row in grid]

